package org.example;

import okhttp3.OkHttpClient;
import okhttp3.Request;
import org.junit.jupiter.api.Test;

import java.io.IOException;

import static org.junit.jupiter.api.Assertions.*;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.sql.*;

class LibraryTest {
    String DB_URL = "jdbc:postgresql://localhost:5433/test_database";
    String DB_USER = "postgres";
    String DB_PASSWORD = "PostgreSQL";

    @Test void appReturnesMovieGenres() {
        OkHttpClient client = new OkHttpClient();

        Request request = new Request.Builder()
                .url("http://localhost:4000/v1/genres").build();

        try {
            String response = client.newCall(request).execute().body().string();
            System.out.println(response);
            assertTrue(response.contains("Adventure"));
        } catch (Exception e) {
            fail("Exception:" + e.getMessage());
        }
    }

    @Test
    void moviesListIsNotEmpty() {
        String fileName = "";
        try {
            Connection connection = DriverManager.getConnection(
                    DB_URL = "jdbc:postgresql://localhost:5433/test_database",
            DB_USER = "postgres",
            DB_PASSWORD = "PostgreSQL"
            );
            Statement statement = connection.createStatement();
            ResultSet resultSet = statement.executeQuery("SELECT title FROM movies LIMIT 1");

            if (resultSet.next()) {
                fileName = resultSet.getString("title");
            } else {
                fail("Таблица movies пуста");
            }

            assertNotNull(fileName, "Название фильма не должно быть null");
            System.out.println("fileName: " + fileName);
            connection.close();

        } catch (Exception e) {
            fail("Exception: " + e.getMessage());
        }
    }
}